\\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u201d \\u09ac\\u09be \\u201c\\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u201d \\u09b9\\u09bf\\u09b8\\u09be\\u09ac\\u09c7\\u0993 \\u0989\\u09b2\\u09cd\\u09b2\\u09c7\\u0996 \\u0995\\u09b0\\u09be \\u09b9\\u09af\\u09bc) \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0986\\u09ac\\u09a6\\u09cd\\u09a7 \\u09b9\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4, \\u098f\\u0996\\u09be\\u09a8\\u09c7 \\u0989\\u09b2\\u09cd\\u09b2\\u09c7\\u0996 \\u0995\\u09b0\\u09be \\u0985\\u09a4\\u09bf\\u09b0\\u09bf\\u0995\\u09cd\\u09a4 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u098f\\u09ac\\u0982 \\u09a8\\u09c0\\u09a4\\u09bf\\u0997\\u09c1\\u09b2\\u09bf \\u09b8\\u09b9 \\/\\u0985\\u09a5\\u09ac\\u09be \\u09b9\\u09be\\u0987\\u09aa\\u09be\\u09b0\\u09b2\\u09bf\\u0999\\u09cd\\u0995 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0989\\u09aa\\u09b2\\u09ac\\u09cd\\u09a7\\u0964 \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u09c7\\u09b0 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u09aa\\u09cd\\u09b0\\u09af\\u09cb\\u099c\\u09cd\\u09af, \\u09af\\u09be\\u09b0 \\u09ae\\u09a7\\u09cd\\u09af\\u09c7 \\u0995\\u09bf\\u09a8\\u09cd\\u09a4\\u09c1 \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7 \\u09a8\\u09af\\u09bc, \\u09af\\u09be\\u09b0\\u09be \\u09ac\\u09cd\\u09b0\\u09be\\u0989\\u099c\\u09be\\u09b0, \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09c7\\u09a4\\u09be, \\u0997\\u09cd\\u09b0\\u09be\\u09b9\\u0995, \\u09ac\\u09a3\\u09bf\\u0995, \\u0985\\u09a7\\u09bf\\u09ad\\u09c1\\u0995\\u09cd\\u09a4 \\u098f\\u09ac\\u0982 \\u09ac\\u09be \\u09b8\\u09be\\u09ae\\u0997\\u09cd\\u09b0\\u09c0\\u09b0 \\u0985\\u09ac\\u09a6\\u09be\\u09a8\\u0995\\u09be\\u09b0\\u09c0\\u0964<\\/p><p>\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09be \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u0997\\u09c1\\u09b2\\u09bf \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09be\\u09b0 \\u0986\\u0997\\u09c7 \\u09a6\\u09af\\u09bc\\u09be \\u0995\\u09b0\\u09c7 \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09a6\\u09bf \\u09b8\\u09be\\u09ac\\u09a7\\u09be\\u09a8\\u09c7 \\u09aa\\u09a1\\u09bc\\u09c1\\u09a8\\u0964 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u09c7\\u09b0 \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u0985\\u0982\\u09b6 \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09c7, \\u0986\\u09aa\\u09a8\\u09bf \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0986\\u0987\\u09a8\\u09a4 \\u0986\\u09ac\\u09a6\\u09cd\\u09a7 \\u09b9\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09b9\\u09a8\\u0964 \\u0986\\u09aa\\u09a8\\u09bf \\u09af\\u09a6\\u09bf \\u098f\\u0987 \\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u09b0 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09a8\\u09be \\u09b9\\u09a8, \\u09a4\\u09be\\u09b9\\u09b2\\u09c7 \\u0986\\u09aa\\u09a8\\u09bf \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u099f\\u09bf \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09ac\\u09c7\\u09a8 \\u09a8\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\