\u09aa\\u09a8\\u09be\\u09b0 \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09c7 \\u09b8\\u0982\\u0997\\u09c3\\u09b9\\u09c0\\u09a4 \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09a5\\u09c7\\u0995\\u09c7 \\u0989\\u09a6\\u09cd\\u09ad\\u09c2\\u09a4, \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u09b8\\u09be\\u09a5\\u09c7 \\u09b8\\u09ae\\u09cd\\u09aa\\u09b0\\u09cd\\u0995\\u09bf\\u09a4 \\u0985\\u09a8\\u09cd\\u09af \\u0995\\u09cb\\u09a8\\u0993 \\u09a6\\u09be\\u09ac\\u09bf\\u09b0 \\u099c\\u09a8\\u09cd\\u09af, \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09a4\\u09cd\\u09b0\\u09c1\\u099f\\u09bf \\u09b8\\u09b9 \\u0995\\u09bf\\u09a8\\u09cd\\u09a4\\u09c1 \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7 \\u09a8\\u09af\\u09bc \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09bf\\u09b7\\u09af\\u09bc\\u09ac\\u09b8\\u09cd\\u09a4\\u09c1\\u09a4\\u09c7 \\u09ac\\u09be\\u09a6 \\u09aa\\u09a1\\u09bc\\u09be, \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u09ab\\u09b2\\u09c7 \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u09cb \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf \\u09ac\\u09be \\u0995\\u09cd\\u09b7\\u09a4\\u09bf \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09bf\\u09b7\\u09af\\u09bc\\u09ac\\u09b8\\u09cd\\u09a4\\u09c1 (\\u09ac\\u09be \\u09aa\\u09a3\\u09cd\\u09af) \\u09aa\\u09cb\\u09b8\\u09cd\\u099f \\u0995\\u09b0\\u09be, \\u09aa\\u09cd\\u09b0\\u09c7\\u09b0\\u09a3 \\u0995\\u09b0\\u09be \\u09ac\\u09b