\u09be \\u0986\\u09ac\\u09a6\\u09cd\\u09a7 \\u09b9\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4\\u0964 \\u0986\\u09aa\\u09a8\\u09bf \\u098f\\u099f\\u09bf\\u09b0 \\u09b8\\u09be\\u09a5\\u09c7 \\u09b8\\u09ae\\u09cd\\u09aa\\u09b0\\u09cd\\u0995\\u09bf\\u09a4 \\u09a1\\u09c7\\u099f\\u09be \\u0995\\u09cd\\u09b7\\u09a4\\u09bf\\u09b0 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u099d\\u09c1\\u0981\\u0995\\u09bf \\u09ac\\u09b9\\u09a8 \\u0995\\u09b0\\u09c7\\u09a8\\u0964 \\u0986\\u09aa\\u09a8\\u09bf \\u09af\\u09a6\\u09bf \\u098f\\u0987 \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8 \\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09a8\\u09be \\u09b9\\u09a8 \\u09a4\\u09ac\\u09c7 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09a3\\u09cd\\u09af \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u0997\\u09c1\\u09b2\\u09bf \\u09a1\\u09be\\u0989\\u09a8\\u09b2\\u09cb\\u09a1 \\u09ac\\u09be \\u0987\\u09a8\\u09b8\\u09cd\\u099f\\u09b2 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09ac\\u09c7\\u09a8 \\u09a8\\u09be\\u0964<\\/p><p>\\u098f\\u099f\\u09bf \\u098f\\u0995\\u099f\\u09bf \\u09b6\\u09c7\\u09b7-\\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0 \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8 \\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf (\\u201c\\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u201d) autonemo.com.bd (\\u098f\\u0996\\u09be\\u09a8\\u09c7 \\u201d \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8 \\u09aa\\u09cd\\u09b0\\u09a6\\u09be\\u09a8\\u0995\\u09be\\u09b0\\u09c0\\/\\u0986\\u09ae\\u09b0\\u09be\\u201d \\u098f\\u09b0 \\u09aa\\u09b0\\u09c7) \\u098f\\u09ac\\u0982 \\u0986\\u09aa\\u09a8\\u09bf, \\u098f\\u0995\\u099c\\u09a8 \\u09ac\\u09cd\\u09af\\u0995\\u09cd\\u09a4\\u09bf \\u09b9\\u09bf\\u09b8\\u09be\\u09ac\\u09c7 \\u09ac\\u09be \\u098f\\u0995\\u099f\\u09bf \\u09ac\\u09cd\\u09af\\u09ac\\u09b8\\u09be\\u09af\\u09bc\\u09bf\\u0995 \\u09b8\\u09a4\\u09cd\\u09a4\\u09be \\u09b9\\u09bf\\u09b8\\u09be\\u09ac\\u09c7 (\\u098f\\u0996\\u09be\\u09a8\\u09c7 \\u201c\\u0986\\u09aa\\u09a8\\u09bf\\u201d \\u098f\\u09b0 \\u09aa\\u09b0\\u09c7), \\u09af\\u09be\\u09b0\\u09be \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0995\\u09cb\\u09ae\\u09cd\\u09aa\\u09be\\u09a8\\u09c0\\u09b0 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09af\\u09bc, \\u09ac\\u09bf\\u099c\\u09cd\\u099e\\u09be\\u09aa\\u09a8 \\u09ac\\u09be \\u09ac\\u09bf\\u09a4\\u09b0\\u09a3 \\u0995\\u09b0\\u09be \\u09af\\u09c7\\u0995\\u09cb\\u09a8 \\u09aa\\u09a3\\u09cd\\u09af \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be (\\u098f\\u0996\\u09be\\u09a8\\u09c7 \\u201c\\u09aa\\u09a3\\u09cd\\u09af\\u201d \\u098f\\u09b0 \\u09aa\\u09b0\\u09c7) \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09be\\u09b0 \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8 \\u09a6\\u09c7\\u0993\\u09af\\u09bc\\u09be \\u09b9\\u099a\\u09cd\\u099b\\u09c7\\u0964<br \\/>\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09aa\\u09b0\\u09bf\\u09a6\\u09b0\\u09cd\\u09b6\\u09a8 \\u0995\\u09b0\\u09c7 \\u098f\\u09ac\\u0982\\/\\u0985\\u09a5\\u09ac\\u09be \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0995\\u09be\\u099b \\u09a5\\u09c7\\u0995\\u09c7 \\u0995\\u09bf\\u099b\\u09c1 \\u0995\\u09c7\\u09a8\\u09be\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7, \\u0986\\u09aa\\u09a8\\u09bf \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u09c7\\u09b0 \\u098f\\u0995\\u099c\\u09a8 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0 \\u09b9\\u09af\\u09bc\\u09c7 \\u0993\\u09a0\\u09c7\\u09a8 \\u098f\\u09ac\\u0982 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u201c\\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u201d-\\u098f \\u09a8\\u09bf\\u09af\\u09c1\\u0995\\u09cd\\u09a4 \\u09b9\\u09a8\\u0964 \\u098f\\u0987 \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09b8\\u09ae\\u09cd\\u09aa\\u09c3\\u0995\\u09cd\\u09a4\\u09a4\\u09be\\u09b0 \\u0985\\u09b0\\u09cd\\u09a5 \\u09b9\\u09b2 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0 \\u09a8\\u09bf\\u09ae\\u09cd\\u09a8\\u09b2\\u09bf\\u0996\\u09bf\\u09a4 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 (\\u201c\\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u201d, \\u201c\\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u201d \\u09ac\\u09be \\u201c\\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u201d \\u09b9\\u09bf\\u09b8\\u09be\\u09ac\\u09c7\\u0993 \\u0989\\u09b2\\u09cd\\u09b2\\u09c7\\u0996 \\u0995\\u09b0\\u09be \\u09b9\\u09af\\u09bc) \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0986\\u09ac\\u09a6\\u09cd\\u09a7 \\u09b9\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4, \\u098f\\u0996\\u09be\\u09a8\\u09c7 \\u0989\\u09b2\\u09cd\\u09b2\\u09c7\\u0996 \\u0995\\u09b0\\u09be \\u0985\\u09a4\\u09bf\\u09b0\\u09bf\\u0995\\u09cd\\u09a4 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u098f\\u09ac\\u0982 \\u09a8\\u09c0\\u09a4\\u09bf\\u0997\\u09c1\\u09b2\\u09bf \\u09b8\\u09b9 \\/\\u0985\\u09a5\\u09ac\\u09be \\u09b9\\u09be\\u0987\\u09aa\\u09be\\u09b0\\u09b2\\u09bf\\u0999\\u09cd\\u0995 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0989\\u09aa\\u09b2\\u09ac\\u09cd\\u09a7\\u0964 \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u09c7\\u09b0 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u09aa\\u09cd\\u09b0\\u09af\\u09cb\\u099c\\u09cd\\u09af, \\u09af\\u09be\\u09b0 \\u09ae\\u09a7\\u09cd\\u09af\\u09c7 \\u0995\\u09bf\\u09a8\\u09cd\\u09a4\\u09c1 \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7 \\u09a8\\u09af\\u09bc, \\u09af\\u09be\\u09b0\\u09be \\u09ac\\u09cd\\u09b0\\u09be\\u0989\\u099c\\u09be\\u09b0, \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09c7\\u09a4\\u09be, \\u0997\\u09cd\\u09b0\\u09be\\u09b9\\u0995, \\u09ac\\u09a3\\u09bf\\u0995, \\u0985\\u09a7\\u09bf\\u09ad\\u09c1\\u0995\\u09cd\\u09a4 \\u098f\\u09ac\\u0982 \\u09ac\\u09be \\u09b8\\u09be\\u09ae\\u0997\\u09cd\\u09b0\\u09c0\\u09b0 \\u0985\\u09ac\\u09a6\\u09be\\u09a8\\u0995\\u09be\\u09b0\\u09c0\\u0964<\\/p><p>\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09be \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u0997\\u09c1\\u09b2\\u09bf \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09be\\u09b0 \\u0986\\u0997\\u09c7 \\u09a6\\u09af\\u09bc\\u09be \\u0995\\u09b0\\u09c7 \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09a6\\u09bf \\u09b8\\u09be\\u09ac\\u09a7\\u09be\\u09a8\\u09c7 \\u09aa\\u09a1\\u09bc\\u09c1\\u09a8\\u0964 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u09c7\\u09b0 \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u0985\\u0982\\u09b6 \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09c7, \\u0986\\u09aa\\u09a8\\u09bf \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0986\\u0987\\u09a8\\u09a4 \\u0986\\u09ac\\u09a6\\u09cd\\u09a7 \\u09b9\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09b9\\u09a8\\u0964 \\u0986\\u09aa\\u09a8\\u09bf \\u09af\\u09a6\\u09bf \\u098f\\u0987 \\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u09b0 \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09a8\\u09be \\u09b9\\u09a8, \\u09a4\\u09be\\u09b9\\u09b2\\u09c7 \\u0986\\u09aa\\u09a8\\u09bf \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f\\u099f\\u09bf \\u0985\\u09cd\\u09af\\u09be\\u0995\\u09cd\\u09b8\\u09c7\\u09b8 \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09ac\\u09c7\\u09a8 \\u09a8\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09ac\\u09c7\\u09a8 \\u09a8\\u09be\\u0964<\\/p><p>\\u09ac\\u09c8\\u09b6\\u09bf\\u09b7\\u09cd\\u099f\\u09cd\\u09af, \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u09b8\\u09b0\\u099e\\u09cd\\u099c\\u09be\\u09ae\\u0997\\u09c1\\u09b2\\u09bf\\u09b0 \\u0995\\u09cb\\u09a8\\u0993 \\u09a8\\u09a4\\u09c1\\u09a8 \\u09b8\\u0982\\u09af\\u09cb\\u099c\\u09a8\\u0993 \\u09ac\\u09b2\\u09ac\\u09ce \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09b0 \\u0985\\u09a7\\u09c0\\u09a8 \\u09ac\\u09b2\\u09c7 \\u0997\\u09a3\\u09cd\\u09af \\u09b9\\u09ac\\u09c7\\u09f7 \\u0986\\u09aa\\u09a8\\u09bf \\u098f\\u0987 \\u09aa\\u09c3\\u09b7\\u09cd\\u09a0\\u09be\\u09af\\u09bc \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u09b8\\u09ae\\u09af\\u09bc \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09b0 \\u09b8\\u09ac\\u099a\\u09c7\\u09af\\u09bc\\u09c7 \\u09b8\\u09be\\u09ae\\u09cd\\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u0995 \\u09b8\\u0982\\u09b8\\u09cd\\u0995\\u09b0\\u09a3 \\u09aa\\u09b0\\u09cd\\u09af\\u09be\\u09b2\\u09cb\\u099a\\u09a8\\u09be \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09c7\\u09a8\\u0964 \\u0986\\u09ae\\u09b0\\u09be \\u0986\\u09ae\\u09be\\u09a6\\u0