\u09cd\\u09af\\u09a6\\u09cd\\u09ac\\u09be\\u09a3\\u09c0 \\u0995\\u09b0\\u09be \\u09af\\u09be\\u09af\\u09bc \\u09a8\\u09be, \\u098f\\u099f\\u09bf \\u0985\\u09a8\\u09bf\\u09ac\\u09be\\u09b0\\u09cd\\u09af \\u0987\\u09a8\\u09ad\\u09c7\\u09a8\\u09cd\\u099f\\u09b0\\u09bf \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09b8\\u09ae\\u09b8\\u09cd\\u09af\\u09be, \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ae\\u09cd\\u09af\\u09be\\u09a8\\u09c7\\u099c\\u09ae\\u09c7\\u09a8\\u09cd\\u099f \\u09b8\\u09ae\\u09b8\\u09cd\\u09af\\u09be, \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09c7\\u09a4\\u09be \\u09b8\\u09cd\\u099f\\u0995 \\u0986\\u09aa\\u09a1\\u09c7\\u099f \\u09b8\\u09ae\\u09b8\\u09cd\\u09af\\u09be \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09af \\u0995\\u09cb\\u09a8 \\u0985\\u09aa\\u09cd\\u09b0\\u09a4\\u09cd\\u09af\\u09be\\u09b6\\u09bf\\u09a4 \\u0995\\u09be\\u09b0\\u09a3\\u09c7\\u0964<\\/p>\\n<p>\\u09ac\\u09bf\\u09ad\\u09be\\u0997 10 \\u2013 \\u09a8\\u09bf\\u09b7\\u09bf\\u09a6\\u09cd\\u09a7 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0<\\/p>\\n<p>\\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09a4\\u09c7 \\u0989\\u09b2\\u09cd\\u09b2\\u09bf\\u0996\\u09bf\\u09a4 \\u0985\\u09a8\\u09cd\\u09af\\u09be\\u09a8\\u09cd\\u09af \\u09a8\\u09bf\\u09b7\\u09c7\\u09a7\\u09be\\u099c\\u09cd\\u099e\\u09be\\u0997\\u09c1\\u09b2\\u09bf \\u099b\\u09be\\u09a1\\u09bc\\u09be\\u0993, \\u0986\\u09aa\\u09a8\\u09bf \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09be \\u098f\\u09b0 \\u09ac\\u09bf\\u09b7\\u09af\\u09bc\\u09ac\\u09b8\\u09cd\\u09a4\\u09c1 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09be \\u09a8\\u09bf\\u09b7\\u09bf\\u09a6\\u09cd\\u09a7:<\\/p>\\n<p>(\\u0995) \\u0995\\u09cb\\u09a8 \\u09ac\\u09c7\\u0986\\u0987\\u09a8\\u09c0 \\u0989\\u09a6\\u09cd\\u09a6\\u09c7\\u09b6\\u09cd\\u09af\\u09c7;<br>(\\u0996) \\u0985\\u09a8\\u09cd\\u09af\\u09a6\\u09c7\\u09b0\\u0995\\u09c7 \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09c7\\u0986\\u0987\\u09a8\\u09bf \\u0995\\u09be\\u099c \\u09b8\\u09ae\\u09cd\\u09aa\\u09be\\u09a6\\u09a8 \\u09ac\\u09be \\u0985\\u0982\\u09b6\\u0997\\u09cd\\u09b0\\u09b9\\u09a3\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u0985\\u09a8\\u09c1\\u09b0\\u09cb\\u09a7 \\u0995\\u09b0\\u09be; (\\u0997) \\u0995\\u09cb\\u09a8\\u09cb \\u0986\\u09a8\\u09cd\\u09a4\\u09b0\\u09cd\\u099c\\u09be\\u09a4\\u09bf\\u0995, \\u09ab\\u09c7\\u09a1\\u09be\\u09b0\\u09c7\\u09b2, \\u09aa\\u09cd\\u09b0\\u09be\\u09a6\\u09c7\\u09b6\\u09bf\\u0995 \\u09ac\\u09be \\u099c\\u09be\\u09a4\\u09c0\\u09af\\u09bc \\u09aa\\u09cd\\u09b0\\u09ac\\u09bf\\u09a7\\u09be\\u09a8, \\u09a8\\u09bf\\u09af\\u09bc\\u09ae, \\u0986\\u0987\\u09a8, \\u09ac\\u09be \\u09b8\\u09cd\\u09a5\\u09be\\u09a8\\u09c0\\u09af\\u09bc \\u0985\\u09a7\\u09cd\\u09af\\u09be\\u09a6\\u09c7\\u09b6 \\u09b2\\u0999\\u09cd\\u0998\\u09a8 \\u0995\\u09b0\\u09be;<br>(\\u0998) \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09ae\\u09c7\\u09a7\\u09be \\u09b8\\u09ae\\u09cd\\u09aa\\u09a4\\u09cd\\u09a4\\u09bf \\u0985\\u09a7\\u09bf\\u0995\\u09be\\u09b0 \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09af\\u09c7\\u09b0 \\u09ae\\u09c7\\u09a7\\u09be \\u09b8\\u09ae\\u09cd\\u09aa\\u09a4\\u09cd\\u09a4\\u09bf \\u0985\\u09a7\\u09bf\\u0995\\u09be\\u09b0 \\u09b2\\u0999\\u09cd\\u0998\\u09a8 \\u09ac\\u09be \\u09b2\\u0999\\u09cd\\u0998\\u09a8 \\u0995\\u09b0\\u09be;<br>(\\u0999) \\u09b2\\u09bf\\u0999\\u09cd\\u0997, \\u09af\\u09cc\\u09a8 \\u0985\\u09ad\\u09bf\\u09af\\u09cb\\u099c\\u09a8, \\u09a7\\u09b0\\u09cd\\u09ae, \\u099c\\u09be\\u09a4\\u09bf, \\u099c\\u09be\\u09a4\\u09bf, \\u09ac\\u09af\\u09bc\\u09b8, \\u099c\\u09be\\u09a4\\u09c0\\u09af\\u09bc \\u0989\\u09a4\\u09cd\\u09b8 \\u09ac\\u09be \\u0985\\u0995\\u09cd\\u09b7\\u09ae\\u09a4\\u09be\\u09b0 \\u09ad\\u09bf\\u09a4\\u09cd\\u09a4\\u09bf\\u09a4\\u09c7 \\u09b9\\u09af\\u09bc\\u09b0\\u09be\\u09a8\\u09bf, \\u0985\\u09aa\\u09ae\\u09be\\u09a8, \\u0985\\u09aa\\u09ae\\u09be\\u09a8, \\u0995\\u09cd\\u09b7\\u09a4\\u09bf, \\u09ae\\u09be\\u09a8\\u09b9\\u09be\\u09a8\\u09bf, \\u0985\\u09aa\\u09ac\\u09be\\u09a6, \\u0985\\u09aa\\u09ae\\u09be\\u09a8, \\u09ad\\u09af\\u09bc \\u09a6\\u09c7\\u0996\\u09be\\u09a8\\u09cb \\u09ac\\u09be \\u09ac\\u09c8\\u09b7\\u09ae\\u09cd\\u09af \\u0995\\u09b0\\u09be; (\\u099a) \\u09ae\\u09bf\\u09a5\\u09cd\\u09af\\u09be \\u09ac\\u09be \\u09ac\\u09bf\\u09ad\\u09cd\\u09b0\\u09be\\u09a8\\u09cd\\u09a4\\u09bf\\u0995\\u09b0 \\u09a4\\u09a5\\u09cd\\u09af;(g) \\u0986\\u09aa\\u09b2\\u09cb\\u09a1 \\u09ac\\u09be \\u09b8\\u0982\\u0995\\u09cd\\u09b0\\u09ae\\u09a3 \\u09ac\\u09be \\u09ad\\u09be\\u0987\\u09b0\\u09be\\u09b8 \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09af \\u0995\\u09cb\\u09a8\\u09cb \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09a6\\u09c2\\u09b7\\u09bf\\u09a4 \\u0995\\u09cb\\u09a1 \\u09af\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u0995\\u09be\\u09b0\\u09cd\\u09af\\u0995\\u09be\\u09b0\\u09bf\\u09a4\\u09be \\u09ac\\u09be \\u0995\\u09cd\\u09b0\\u09bf\\u09af\\u09bc\\u09be\\u0995\\u09b2\\u09be\\u09aa\\u0995\\u09c7 \\u09aa\\u09cd\\u09b0\\u09ad\\u09be\\u09ac\\u09bf\\u09a4 \\u0995\\u09b0\\u09ac\\u09c7 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09be \\u09af\\u09c7\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09c7 \\u098f\\u09ae\\u09a8 \\u0995\\u09cb\\u09a8\\u09cb \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f, \\u0985\\u09a8\\u09cd\\u09af\\u09be\\u09a8\\u09cd\\u09af \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09be \\u0987\\u09a8\\u09cd\\u099f\\u09be\\u09b0\\u09a8\\u09c7\\u099f; (h) \\u0985\\u09a8\\u09cd\\u09af\\u09c7\\u09b0 \\u09ac\\u09cd\\u09af\\u0995\\u09cd\\u09a4\\u09bf\\u0997\\u09a4 \\u09a4\\u09a5\\u09cd\\u09af \\u09b8\\u0982\\u0997\\u09cd\\u09b0\\u09b9 \\u09ac\\u09be \\u099f\\u09cd\\u09b0\\u09cd\\u09af\\u09be\\u0995 \\u0995\\u09b0\\u09be; ( i ) \\u09b8\\u09cd\\u09aa\\u09cd\\u09af\\u09be\\u09ae, \\u09ab\\u09bf\\u09b6, \\u09ab\\u09be\\u09b0\\u09cd\\u09ae, \\u0985\\u099c\\u09c1\\u09b9\\u09be\\u09a4, \\u09ae\\u09be\\u0995\\u09a1\\u09bc\\u09b8\\u09be \\u09b9\\u09be\\u09ae\\u09be\\u0997\\u09c1\\u09a1\\u09bc\\u09bf \\u09a6\\u09c7\\u0993\\u09af\\u09bc\\u09be \\u09ac\\u09be \\u09b8\\u09cd\\u0995\\u09cd\\u09b0\\u09cd\\u09af\\u09be\\u09aa \\u0995\\u09b0\\u09be;<br>(j) \\u0995\\u09cb\\u09a8 \\u0985\\u09b6\\u09cd\\u09b2\\u09c0\\u09b2 \\u09ac\\u09be \\u0985\\u09a8\\u09c8\\u09a4\\u09bf\\u0995 \\u0989\\u09a6\\u09cd\\u09a6\\u09c7\\u09b6\\u09cd\\u09af\\u09c7; \\u09ac\\u09be (\\u099f) \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u0993 \\u09b8\\u09ae\\u09cd\\u09aa\\u09b0\\u09cd\\u0995\\u09bf\\u09a4 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f, \\u0985\\u09a8\\u09cd\\u09af\\u09be\\u09a8\\u09cd\\u09af \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09be \\u0987\\u09a8\\u09cd\\u099f\\u09be\\u09b0\\u09a8\\u09c7\\u099f\\u09c7\\u09b0 \\u09b8\\u09c1\\u09b0\\u0995\\u09cd\\u09b7\\u09be \\u09ac\\u09c8\\u09b6\\u09bf\\u09b7\\u09cd\\u099f\\u09cd\\u09af\\u0997\\u09c1\\u09b2\\u09bf\\u09a4\\u09c7 \\u09b9\\u09b8\\u09cd\\u09a4\\u0995\\u09cd\\u09b7\\u09c7\\u09aa \\u09ac\\u09be \\u09ac\\u09be\\u09a7\\u09be \\u09a6\\u09c7\\u0993\\u09af\\u09bc\\u09be\\u0964<\\/p>\\n<p>\\u0986\\u09ae\\u09b0\\u09be \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u0993 \\u09b8\\u09ae\\u09cd\\u09aa\\u09b0\\u09cd\\u0995\\u09bf\\u09a4 \\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09ac\\u09a8\\u09cd\\u09a7 \\u0995\\u09b0\\u09be\\u09b0 \\u0985\\u09a7\\u09bf\\u0995\\u09be\\u09b0 \\u09b8\\u0982\\u09b0\\u0995\\u09cd\\u09b7\\u09a3 \\u0995\\u09b0\\u09bf \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09a8\\u09bf\\u09b7\\u09bf\\u09a6\\u09cd\\u09a7 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09b2\\u0999\\u09cd\\u0998\\u09a8\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af\\u0964<\\/p>\\n<p>\\u09a7\\u09be\\u09b0\\u09be 11 \\u2013 \\u0993\\u09af\\u09bc\\u09cd\\u09af\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u0985\\u09b8\\u09cd\\u09ac\\u09c0\\u0995\\u09c3\\u09a4\\u09bf; \\u09a6\\u09be\\u09af\\u09bc\\u09ac\\u09a6\\u09cd\\u09a7\\u09a4\\u09be \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7\\u09a4\\u09be<\\/p>\\n<p>\\u0986\\u09ae\\u09b0\\u09be \\u0997\\u09cd\\u09af\\u09be\\u09b0\\u09be\\u09a8\\u09cd\\u099f\\u09bf \\u09a6\\u09bf\\u0987 \\u09a8\\u09be, \\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u09a8\\u09bf\\u09a7\\u09bf\\u09a4\\u09cd\\u09ac \\u0995\\u09b0\\u09bf \\u09ac\\u09be \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09a6\\u09bf\\u0987 \\u09a8\\u09be \\u09af\\u09c7 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09a8\\u09bf\\u09b0\\u09ac\\u099a\\u09cd\\u099b\\u09bf\\u09a8\\u09cd\\u09a8, \\u09b8\\u09ae\\u09af\\u09bc\\u09cb\\u09aa\\u09af\\u09cb\\u0997\\u09c0, \\u09a8\\u09bf\\u09b0\\u09be\\u09aa\\u09a6 \\u09ac\\u09be \\u09a4\\u09cd\\u09b0\\u09c1\\u099f\\u09bf-\\u09ae\\u09c1\\u0995\\u09cd\\u09a4 \\u09b9\\u09ac\\u09c7\\u0964 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09a5\\u09c7\\u0995\\u09c7 \\u09aa\\u09cd\\u09b0\\u09be\\u09aa\\u09cd\\u09a4 \\u09a4\\u09cd\\u09b0\\u09c1\\u099f\\u09bf \\u09a5\\u09c7\\u0995\\u09c7 \\u09ae\\u09c1\\u0995\\u09cd\\u09a4 \\u09b9\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09c7 \\u098f\\u09ae\\u09a8 \\u09ab\\u09b2\\u09be\\u09ab\\u09b2\\u0997\\u09c1\\u09b2\\u09bf \\u09b8\\u09a0\\u09bf\\u0995 \\u09ac\\u09be \\u09a8\\u09bf\\u09b0\\u09cd\\u09ad\\u09b0\\u09af\\u09cb\\u0997\\u09cd\\u09af \\u09b9\\u09ac\\u09c7 \\u09ac\\u09b2\\u09c7 \\u0986\\u09ae\\u09b0\\u09be \\u09a8\\u09bf\\u09b6\\u09cd\\u099a\\u09af\\u09bc\\u09a4\\u09be \\u09a6\\u09bf\\u0987 \\u09a8\\u09be\\u0964 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0\\u0995\\u09c7 \\u0985\\u09ac\\u09b6\\u09cd\\u09af\\u0987 \\u09ac\\u09c1\\u099d\\u09a4\\u09c7 \\u09b9\\u09ac\\u09c7 \\u09af\\u09c7, \\u09b8\\u09ae\\u09af\\u09bc\\u09c7 \\u09b8\\u09ae\\u09af\\u09bc\\u09c7 \\u0986\\u09ae\\u09b0\\u09be \\u0985\\u09a8\\u09bf\\u09b0\\u09cd\\u09a6\\u09bf\\u09b7\\u09cd\\u099f \\u09b8\\u09ae\\u09af\\u09bc\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u099f\\u09bf \\u09b8\\u09b0\\u09bf\\u09af\\u09bc\\u09c7 \\u09ab\\u09c7\\u09b2\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09bf \\u09ac\\u09be \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09b8\\u09ae\\u09af\\u09bc\\u09c7, \\u09ac\\u09bf\\u09ad\\u09bf\\u09a8\\u09cd\\u09a8 \\u09aa\\u09b0\\u09bf\\u09b8\\u09cd\\u09a5\\u09bf\\u09a4\\u09bf\\u09a4\\u09c7, \\u0986\\u09aa\\u09a8\\u09be\\u0995\\u09c7 \\u09aa\\u09c2\\u09b0\\u09cd\\u09ac \\u09ac\\u09bf\\u099c\\u09cd\\u099e\\u09aa\\u09cd\\u09a4\\u09bf \\u099b\\u09be\\u09a1\\u09bc\\u09be\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u099f\\u09bf \\u09ac\\u09be\\u09a4\\u09bf\\u09b2 \\u0995\\u09b0\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09bf\\u09f7<\\/p>\\n<p>\\u0986\\u09aa\\u09a8\\u09bf \\u09b8\\u09cd\\u09aa\\u09b7\\u09cd\\u099f\\u09ad\\u09be\\u09ac\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09b9\\u09a8 \\u09af\\u09c7 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7 \\u0985\\u0995\\u09cd\\u09b7\\u09ae\\u09a4\\u09be \\u09b6\\u09c1\\u09a7\\u09c1\\u09ae\\u09be\\u09a4\\u09cd\\u09b0 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u099d\\u09c1\\u0981\\u0995\\u09bf\\u0964 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u098f\\u09ac\\u0982 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7 \\u0986\\u09aa\\u09a8\\u09be\\u0995\\u09c7 \\u09b8\\u09b0\\u09ac\\u09b0\\u09be\\u09b9 \\u0995\\u09b0\\u09be \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u09aa\\u09a3\\u09cd\\u09af \\u098f\\u09ac\\u0982 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u0997\\u09c1\\u09b2\\u09bf (\\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u09b8\\u09cd\\u09aa\\u09b7\\u09cd\\u099f\\u09ad\\u09be\\u09ac\\u09c7 \\u09ac\\u09b2\\u09be \\u099b\\u09be\\u09a1\\u09bc\\u09be) \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u2018\\u09af\\u09c7\\u09ae\\u09a8 \\u0986\\u099b\\u09c7\\u2019 \\u098f\\u09ac\\u0982 \\u2018\\u09af\\u09c7\\u09ae\\u09a8 \\u0989\\u09aa\\u09b2\\u09ac\\u09cd\\u09a7\\u2019 \\u09aa\\u09cd\\u09b0\\u09a6\\u09be\\u09a8 \\u0995\\u09b0\\u09be \\u09b9\\u09af\\u09bc, \\u0995\\u09cb\\u09a8\\u09cb \\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u09a8\\u09bf\\u09a7\\u09bf\\u09a4\\u09cd\\u09ac, \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4 \\u099b\\u09be\\u09a1\\u09bc\\u09be\\u0987, \\u09aa\\u09cd\\u09b0\\u0995\\u09be\\u09b6 \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09a4\\u09b0\\u09cd\\u09a8\\u09bf\\u09b9\\u09bf\\u09a4, \\u09b8\\u09ae\\u09b8\\u09cd\\u09a4 \\u0985\\u09a8\\u09cd\\u09a4\\u09b0\\u09cd\\u09a8\\u09bf\\u09b9\\u09bf\\u09a4 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b8\\u09be\\u09af\\u09bc\\u09bf\\u0995\\u09a4\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0, \\u09ac\\u09cd\\u09af\\u09ac\\u09b8\\u09be\\u09af\\u09bc\\u09bf\\u0995 \\u0997\\u09c1\\u09a3\\u09ae\\u09be\\u09a8, \\u098f\\u0995\\u099f\\u09bf \\u09a8\\u09bf\\u09b0\\u09cd\\u09a6\\u09bf\\u09b7\\u09cd\\u099f \\u0989\\u09a6\\u09cd\\u09a6\\u09c7\\u09b6\\u09cd\\u09af\\u09c7 \\u09ab\\u09bf\\u099f\\u09a8\\u09c7\\u09b8, \\u09b8\\u09cd\\u09a5\\u09be\\u09af\\u09bc\\u09bf\\u09a4\\u09cd\\u09ac, \\u09b6\\u09bf\\u09b0\\u09cb\\u09a8\\u09be\\u09ae \\u098f\\u09ac\\u0982 \\u0985 \\u09b2\\u0999\\u09cd\\u0998\\u09a8\\u0964<\\/p>\\n<p>\\u0995\\u09cb\\u09a8\\u09cb \\u0985\\u09ac\\u09b8\\u09cd\\u09a5\\u09be\\u09a4\\u09c7\\u0987 carclinic.com.bd, \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u0995, \\u0995\\u09b0\\u09cd\\u09ae\\u0995\\u09b0\\u09cd\\u09a4\\u09be, \\u0995\\u09b0\\u09cd\\u09ae\\u099a\\u09be\\u09b0\\u09c0, \\u09b8\\u09b9\\u09af\\u09cb\\u0997\\u09c0, \\u098f\\u099c\\u09c7\\u09a8\\u09cd\\u099f, \\u09a0\\u09bf\\u0995\\u09be\\u09a6\\u09be\\u09b0, \\u0987\\u09a8\\u09cd\\u099f\\u09be\\u09b0\\u09cd\\u09a8, \\u09b8\\u09b0\\u09ac\\u09b0\\u09be\\u09b9\\u0995\\u09be\\u09b0\\u09c0, \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09c7\\u09a4\\u09be, \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09aa\\u09cd\\u09b0\\u09a6\\u09be\\u09a8\\u0995\\u09be\\u09b0\\u09c0 \\u09ac\\u09be \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8\\u09a6\\u09be\\u09a4\\u09be\\u09b0\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u0986\\u0998\\u09be\\u09a4, \\u0995\\u09cd\\u09b7\\u09a4\\u09bf, \\u09a6\\u09be\\u09ac\\u09bf \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09aa\\u09cd\\u09b0\\u09a4\\u09cd\\u09af\\u0995\\u09cd\\u09b7, \\u09aa\\u09b0\\u09cb\\u0995\\u09cd\\u09b7, \\u0986\\u09a8\\u09c1\\u09b7\\u0999\\u09cd\\u0997\\u09bf\\u0995 \\u0998\\u099f\\u09a8\\u09be\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u09a6\\u09be\\u09af\\u09bc\\u09c0 \\u09a5\\u09be\\u0995\\u09ac\\u09c7 \\u09a8\\u09be , \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7\\u09a4\\u09be \\u099b\\u09be\\u09a1\\u09bc\\u09be\\u0987, \\u09b9\\u09be\\u09b0\\u09be\\u09a8\\u09cb \\u09b2\\u09be\\u09ad, \\u09b9\\u09be\\u09b0\\u09be\\u09a8\\u09cb \\u09b0\\u09be\\u099c\\u09b8\\u09cd\\u09ac, \\u09b9\\u09be\\u09b0\\u09be\\u09a8\\u09cb \\u09b8\\u099e\\u09cd\\u099a\\u09af\\u09bc, \\u09a1\\u09c7\\u099f\\u09be\\u09b0 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf, \\u09aa\\u09cd\\u09b0\\u09a4\\u09bf\\u09b8\\u09cd\\u09a5\\u09be\\u09aa\\u09a8\\u09c7\\u09b0 \\u0996\\u09b0\\u099a, \\u09ac\\u09be \\u0985\\u09a8\\u09c1\\u09b0\\u09c2\\u09aa \\u0995\\u09cb\\u09a8\\u09cb \\u0995\\u09cd\\u09b7\\u09a4\\u09bf, \\u099a\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u09b0 \\u09ad\\u09bf\\u09a4\\u09cd\\u09a4\\u09bf\\u09a4\\u09c7 \\u09b9\\u09cb\\u0995 \\u09a8\\u09be \\u0995\\u09c7\\u09a8, \\u09a8\\u09bf\\u09b0\\u09cd\\u09af\\u09be\\u09a4\\u09a8 (\\u0985\\u09ac\\u09b9\\u09c7\\u09b2\\u09be \\u09b8\\u09b9), \\u0995\\u09a0\\u09cb\\u09b0 \\u09a6\\u09be\\u09af\\u09bc\\u09ac\\u09a6\\u09cd\\u09a7\\u09a4\\u09be \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09af\\u09a5\\u09be\\u09af\\u09bc, \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u0995\\u09b0\\u09c7 \\u09b8\\u0982\\u0997\\u09c3\\u09b9\\u09c0\\u09a4 \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u09a5\\u09c7\\u0995\\u09c7 \\u0989\\u09a6\\u09cd\\u09ad\\u09c2\\u09a4, \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u0993 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u09b8\\u09be\\u09a5\\u09c7 \\u09b8\\u09ae\\u09cd\\u09aa\\u09b0\\u09cd\\u0995\\u09bf\\u09a4 \\u0985\\u09a8\\u09cd\\u09af \\u0995\\u09cb\\u09a8\\u0993 \\u09a6\\u09be\\u09ac\\u09bf\\u09b0 \\u099c\\u09a8\\u09cd\\u09af, \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u0993 \\u09a4\\u09cd\\u09b0\\u09c1\\u099f\\u09bf \\u09b8\\u09b9 \\u0995\\u09bf\\u09a8\\u09cd\\u09a4\\u09c1 \\u09b8\\u09c0\\u09ae\\u09be\\u09ac\\u09a6\\u09cd\\u09a7 \\u09a8\\u09af\\u09bc \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09bf\\u09b7\\u09af\\u09bc\\u09ac\\u09b8\\u09cd\\u09a4\\u09c1\\u09a4\\u09c7 \\u09ac\\u09be\\u09a6 \\u09aa\\u09a1\\u09bc\\u09be, \\u09ac\\u09be \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u09c7\\u09b0 \\u09ab\\u09b2\\u09c7 \\u09af\\u09c7 \\u0995\\u09cb\\u09a8\\u09cb \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf \\u09ac\\u09be \\u0995\\u09cd\\u09b7\\u09a4\\u09bf \\u09ac\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09bf\\u09b7\\u09af\\u09bc\\u09ac\\u09b8\\u09cd\\u09a4\\u09c1 (\\u09ac\\u09be \\u09aa\\u09a3\\u09cd\\u09af) \\u09aa\\u09cb\\u09b8\\u09cd\\u099f \\u0995\\u09b0\\u09be, \\u09aa\\u09cd\\u09b0\\u09c7\\u09b0\\u09a3 \\u0995\\u09b0\\u09be \\u09ac\\u09be \\u0985\\u09a8\\u09cd\\u09af\\u09ad\\u09be\\u09ac\\u09c7 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7 \\u0989\\u09aa\\u09b2\\u09ac\\u09cd\\u09a7 \\u0995\\u09b0\\u09be \\u09b9\\u09af\\u09bc\\u09c7\\u099b\\u09c7, \\u098f\\u09ae\\u09a8\\u0995\\u09bf \\u09af\\u09a6\\u09bf \\u09a4\\u09be\\u09a6\\u09c7\\u09b0 \\u09b8\\u09ae\\u09cd\\u09ad\\u09be\\u09ac\\u09a8\\u09be\\u09b0 \\u09aa\\u09b0\\u09be\\u09ae\\u09b0\\u09cd\\u09b6 \\u09a6\\u09c7\\u0993\\u09af\\u09bc\\u09be \\u09b9\\u09af\\u09bc\\u0964<\\/p>\\n<p>\\u098f\\u099f\\u09be\\u0993 \\u09ac\\u09b2\\u09be \\u0986\\u09ac\\u09b6\\u09cd\\u09af\\u0995 \\u09af\\u09c7 carclinic.com.bd-\\u098f\\u09b0 \\u09ac\\u09c7\\u09b6\\u09bf\\u09b0\\u09ad\\u09be\\u0997 \\u09aa\\u09a3\\u09cd\\u09af\\u0987 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09ac\\u09b9\\u09a8 \\u0995\\u09b0\\u09c7, \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0 \\u09b8\\u09b0\\u09be\\u09b8\\u09b0\\u09bf \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09cd\\u09b0\\u09cd\\u09af\\u09be\\u09a8\\u09cd\\u09a1 \\u0985\\u09a8\\u09c1\\u09ae\\u09cb\\u09a6\\u09bf\\u09a4 \\u09b8\\u09be\\u09b0\\u09cd\\u09ad\\u09bf\\u09b8\\u09bf\\u0982 \\u09aa\\u09af\\u09bc\\u09c7\\u09a8\\u09cd\\u099f\\u09c7 \\u09ac\\u09be \\u0985\\u099f\\u09cb\\u09a8\\u09c7\\u09ae\\u09cb\\u09b0 \\u09ae\\u09be\\u09a7\\u09cd\\u09af\\u09ae\\u09c7\\u0993 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09aa\\u09c7\\u09a4\\u09c7 \\u09aa\\u09be\\u09b0\\u09c7\\u09a8 \\u0964<\\/p>\\n<p>\\u09af\\u09be\\u0987\\u09b9\\u09cb\\u0995, \\u09aa\\u09cd\\u09b0\\u09a4\\u09cd\\u09af\\u0995\\u09cd\\u09b7 \\u09ac\\u09be \\u09aa\\u09b0\\u09cb\\u0995\\u09cd\\u09b7 \\u09af\\u09be\\u0987 \\u09b9\\u09cb\\u0995 \\u09a8\\u09be \\u0995\\u09c7\\u09a8 \\u0995\\u09cb\\u09a8\\u09cb \\u0986\\u0998\\u09be\\u09a4, \\u0995\\u09cd\\u09b7\\u09a4\\u09bf \\u09ac\\u09be \\u0995\\u09cd\\u09b7\\u09a4\\u09bf\\u09b0 \\u09ab\\u09b2\\u09c7 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0, \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09aa\\u09cd\\u09b0\\u09a6\\u09be\\u09a8\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u0985\\u099f\\u09cb\\u09a8\\u09c7\\u09ae\\u09cb\\u0995\\u09c7 \\u09a6\\u09be\\u09af\\u09bc\\u09ac\\u09a6\\u09cd\\u09a7 \\u0995\\u09b0\\u09ac\\u09c7 \\u09a8\\u09be, \\u09a4\\u09ac\\u09c7 \\u09b6\\u09b0\\u09cd\\u09a4 \\u09a5\\u09be\\u0995\\u09c7 \\u09af\\u09c7, \\u098f\\u0987 \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09aa\\u09cd\\u09b0\\u09a4\\u09cd\\u09af\\u0995\\u09cd\\u09b7 \\u09ac\\u09be \\u09aa\\u09b0\\u09cb\\u0995\\u09cd\\u09b7 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0 \\u098f\\u09ac\\u0982 \\u098f\\u09b0 \\u09ab\\u09b2\\u09be\\u09ab\\u09b2\\u0997\\u09c1\\u09b2\\u09bf \\u0995\\u09ad\\u09be\\u09b0 \\u09ac\\u09be \\u09b8\\u09ae\\u09b0\\u09cd\\u09a5\\u09bf\\u09a4 \\u09a8\\u09af\\u09bc\\u0964 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09b8\\u09b9\\u0995\\u09be\\u09b0\\u09c7 \\u09aa\\u09a3\\u09cd\\u09af\\u09c7\\u09b0 \\u0985\\u09a7\\u09c0\\u09a8\\u09c7 \\u09ac\\u09bf\\u09a7\\u09be\\u09a8\\u0964<\\/p>\\n<p>\\u0986\\u09b0\\u0993 \\u09a4\\u09a5\\u09cd\\u09af\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af, \\u0985\\u09a8\\u09c1\\u0997\\u09cd\\u09b0\\u09b9 \\u0995\\u09b0\\u09c7 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u0993\\u09af\\u09bc\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u099f\\u09bf \\u09a8\\u09c0\\u09a4\\u09bf \\u09aa\\u09c3\\u09b7\\u09cd\\u09a0\\u09be \\u09a6\\u09c7\\u0996\\u09c1\\u09a8\\u0964<\\/p>\\n<p>\\u09ac\\u09bf\\u09ad\\u09be\\u0997 12 \\u2013 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf\\u09aa\\u09c2\\u09b0\\u09a3<\\/p>\\n<p>\\u0993\\u09af\\u09bc\\u09c7\\u09ac\\u09b8\\u09be\\u0987\\u099f \\u098f\\u09ac\\u0982 \\u098f\\u09b0 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u0997\\u09c1\\u09b2\\u09bf\\u09b0 \\u098f\\u0995\\u099c\\u09a8 \\u09ac\\u09cd\\u09af\\u09ac\\u09b9\\u09be\\u09b0\\u0995\\u09be\\u09b0\\u09c0 \\u09b9\\u09bf\\u09b8\\u09be\\u09ac\\u09c7, \\u0986\\u09aa\\u09a8\\u09bf carclinic.com.bd \\u0995\\u09c7 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf\\u09aa\\u09c2\\u09b0\\u09a3 \\u09a6\\u09bf\\u09a4\\u09c7, \\u09b0\\u0995\\u09cd\\u09b7\\u09be \\u0995\\u09b0\\u09a4\\u09c7 \\u098f\\u09ac\\u0982 \\u09a7\\u09b0\\u09c7 \\u09b0\\u09be\\u0996\\u09a4\\u09c7 \\u09b8\\u09ae\\u09cd\\u09ae\\u09a4 \\u09b9\\u09a8 \\u098f\\u09ac\\u0982 \\u0986\\u09ae\\u09be\\u09a6\\u09c7\\u09b0 \\u09aa\\u09bf\\u09a4\\u09be\\u09ae\\u09be\\u09a4\\u09be, \\u09b8\\u09b9\\u09be\\u09af\\u09bc\\u0995, \\u09b8\\u09b9\\u09af\\u09cb\\u0997\\u09c0, \\u0985\\u0982\\u09b6\\u09c0\\u09a6\\u09be\\u09b0, \\u0995\\u09b0\\u09cd\\u09ae\\u0995\\u09b0\\u09cd\\u09a4\\u09be, \\u09aa\\u09b0\\u09bf\\u099a\\u09be\\u09b2\\u0995, \\u098f\\u099c\\u09c7\\u09a8\\u09cd\\u099f, \\u09a0\\u09bf\\u0995\\u09be\\u09a6\\u09be\\u09b0, \\u09b2\\u09be\\u0987\\u09b8\\u09c7\\u09a8\\u09cd\\u09b8\\u09a6\\u09be\\u09a4\\u09be, \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be \\u09aa\\u09cd\\u09b0\\u09a6\\u09be\\u09a8\\u0995\\u09be\\u09b0\\u09c0, \\u0989\\u09aa-\\u0995\\u09a8\\u09cd\\u099f\\u09cd\\u09b0\\u09be\\u0995\\u09cd\\u099f\\u09b0, \\u09b8\\u09b0\\u09ac\\u09b0\\u09be\\u09b9\\u0995\\u09be\\u09b0\\u09c0, \\u09ac\\u09bf\\u0995\\u09cd\\u09b0\\u09c7\\u09a4\\u09be, \\u0987\\u09a8\\u09cd\\u099f\\u09be\\u09b0\\u09cd\\u09a8 \\u098f\\u09ac\\u0982 \\u0995\\u09b0\\u09cd\\u09ae\\u099a\\u09be\\u09b0\\u09c0, \\u09af\\u09c7\\u0995\\u09cb\\u09a8\\u09cb \\u09a6\\u09be\\u09ac\\u09bf \\u09ac\\u09be \\u09a6\\u09be\\u09ac\\u09bf \\u09a5\\u09c7\\u0995\\u09c7 \\u0995\\u09cd\\u09b7\\u09a4\\u09bf\\u0995\\u09be\\u09b0\\u0995 \\u09a8\\u09af\\u09bc, \\u09af\\u09c1\\u0995\\u09cd\\u09a4\\u09bf\\u09b8\\u0999\\u09cd\\u0997\\u09a4 \\u0985\\u09cd\\u09af\\u09be\\u099f\\u09b0\\u09cd\\u09a8\\u09bf \\u09ab\\u09bf \\u09b8\\u09b9, \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u09ac\\u09be \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09b2\\u0999\\u09cd\\u0998\\u09a8\\u09c7\\u09b0 \\u0995\\u09be\\u09b0\\u09a3\\u09c7 \\u09ac\\u09be \\u09a4\\u09be\\u09a6\\u09c7\\u09b0 \\u09b0\\u09c7\\u09ab\\u09be\\u09b0\\u09c7\\u09a8\\u09cd\\u09b8 \\u09ac\\u09be \\u0986\\u09aa\\u09a8\\u09be\\u09b0 \\u09b2\\u0999\\u09cd\\u0998\\u09a8\\u09c7\\u09b0 \\u099c\\u09a8\\u09cd\\u09af \\u0985\\u09a8\\u09cd\\u09a4\\u09b0\\u09cd\\u09ad\\u09c1\\u0995\\u09cd\\u09a4 \\u09af\\u09c7\\u0995\\u09cb\\u09a8 \\u09a8\\u09a5\\u09bf\\u09b0 \\u0995\\u09be\\u09b0\\u09a3\\u09c7 \\u09ac\\u09be \\u0989\\u09a6\\u09cd\\u09ad\\u09c2\\u09a4 \\u0995\\u09cb\\u09a8\\u09cb \\u09a4\\u09c3\\u09a4\\u09c0\\u09af\\u09bc \\u09aa\\u0995\\u09cd\\u09b7\\u09c7\\u09b0 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0995\\u09b0\\u09be \\u0995\\u09cb\\u09a8\\u09cb \\u0986\\u0987\\u09a8 \\u09ac\\u09be \\u09a4\\u09c3\\u09a4\\u09c0\\u09af\\u09bc \\u09aa\\u0995\\u09cd\\u09b7\\u09c7\\u09b0 \\u0985\\u09a7\\u09bf\\u0995\\u09be\\u09b0\\u0964<\\/p>\\n<p>\\u09ac\\u09bf\\u09ad\\u09be\\u0997 13 \\u2013 \\u09ac\\u09bf\\u09ad\\u09be\\u099c\\u09a8\\u09af\\u09cb\\u0997\\u09cd\\u09af\\u09a4\\u09be<\\/p>\\n<p>\\u09af\\u09a6\\u09bf \\u098f\\u0987 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be\\u09b0 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0\\u09b0 \\u0995\\u09cb\\u09a8\\u09cb \\u09ac\\u09bf\\u09a7\\u09be\\u09a8 \\u09ac\\u09c7\\u0986\\u0987\\u09a8\\u09bf, \\u0985\\u0995\\u09be\\u09b0\\u09cd\\u09af\\u0995\\u09b0 \\u09ac\\u09be \\u0985\\u09aa\\u09cd\\u09b0\\u09af\\u09bc\\u09cb\\u0997\\u09af\\u09cb\\u0997\\u09cd\\u09af \\u09ac\\u09b2\\u09c7 \\u09a8\\u09bf\\u09b0\\u09cd\\u09a7\\u09be\\u09b0\\u09a3 \\u0995\\u09b0\\u09be \\u09b9\\u09af\\u09bc, \\u09a4\\u09ac\\u09c7 \\u098f\\u0987 \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09ac\\u09bf\\u09a7\\u09be\\u09a8 \\u09aa\\u09cd\\u09b0\\u09af\\u09cb\\u099c\\u09cd\\u09af \\u0986\\u0987\\u09a8 \\u09a6\\u09cd\\u09ac\\u09be\\u09b0\\u09be \\u0985\\u09a8\\u09c1\\u09ae\\u09cb\\u09a6\\u09bf\\u09a4 \\u09b8\\u09ae\\u09cd\\u09aa\\u09c2\\u09b0\\u09cd\\u09a3 \\u09aa\\u09b0\\u09bf\\u09ae\\u09be\\u09a3\\u09c7 \\u09aa\\u09cd\\u09b0\\u09af\\u09bc\\u09cb\\u0997\\u09af\\u09cb\\u0997\\u09cd\\u09af \\u09b9\\u09ac\\u09c7, \\u098f\\u09ac\\u0982 \\u0985\\u09aa\\u09cd\\u09b0\\u09af\\u09bc\\u09cb\\u0997\\u09af\\u09cb\\u0997\\u09cd\\u09af \\u0985\\u0982\\u09b6\\u099f\\u09bf\\u0995\\u09c7 \\u098f\\u0987 \\u09b6\\u09b0\\u09cd\\u09a4\\u09be\\u09ac\\u09b2\\u09c0 \\u09a5\\u09c7\\u0995\\u09c7 \\u09ac\\u09bf\\u099a\\u09cd\\u099b\\u09bf\\u09a8\\u09cd\\u09a8 \\u09ac\\u09b2\\u09c7 \\u0997\\u09a3\\u09cd\\u09af \\u0995\\u09b0\\u09be \\u09b9\\u09ac\\u09c7 \\u09aa\\u09b0\\u09bf\\u09b7\\u09c7\\u09ac\\u09be, \\u098f\\u0987 \\u09a7\\u09b0\\u09a8\\u09c7\\u09b0 \\u09b8\\u0982\\u0995\\u09b2\\u09cd\\u09aa \\u0985\\u09a8\\u09cd\\u09af \\u0995\\u09cb\\u09a8\\u0993 \\u0985\\u09ac\\u09b6\\u09bf\\u09b7\\u09cd\\u099f \\u09ac\\u09bf\\u09a7\\u09be\\u09a8\\u09c7\\u09b0 \\u09ac\\u09c8\\u09a7\\u09a4\\u09be \\u098f\\u09ac\\u0982 \\u09aa\\u09cd\\u09b0\\u09af\\u09bc\\u09cb\\u0997\\u09af\\u09cb\\u0997\\u09cd\\u09af\\u09a4\\u09be\\u0995\\u09c7 \\u09aa\\u09cd\\u09b0\\u09ad\\u09be\\u09ac\\u09bf\\u09a4 \\u0995\\u09b0\\u