(10702, 1, '2024-06-24 06:04:29', '2024-06-24 06:04:29', '<h3>Motul 7100 4T SEMI SYNTHEIC 20W50 Specifications</h3>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td>Brand</td>\r\n<td>Motul</td>\r\n</tr>\r\n<tr>\r\n<td>Model</td>\r\n<td>7100 4T</td>\r\n</tr>\r\n<tr>\r\n<td>Engine oil type</td>\r\n<td>100% Synthetic, Estercore, FLS &gt; 14</td>\r\n</tr>\r\n<tr>\r\n<td>Viscosity</td>\r\n<td>20W50</td>\r\n</tr>\r\n<tr>\r\n<td>API</td>\r\n<td>SM, HC- Tech</td>\r\n</tr>\r\n<tr>\r\n<td>JASO</td>\r\n<td>MA2 4- Stroke moto</td>\r\n</tr>\r\n<tr>\r\n<td>Volume</td>\r\n<td>1 Liter</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h3>Performance and Benefits:</h3>\r\n<ul>\r\n 	<li>Help to get smooth clutch control.</li>\r\n 	<li>Reduces engine vibration and noise.</li>\r\n 	<li>Enhanced thermal stability.</li>\r\n 	<li>Increase the life of gear and clutch.</li>\r\n 	<li>meets the JASO MA2 and API SM specification.</li>\r\n</ul>', 'Motul 7100 4T 20W50', '', 'publish', 'open', 'closed', '', 'motul-7100-4t-20w50', '', '', '2024-07-03 07:47:39', '2024-07-03 07:47:39', '', 0, 'https://carclinic.com.bd/?post_type=product&#038;p=10702', 0, 'product', '', 0),
